{
  "findings": [
    {
      "check_id": "CKV_GCP_12",
      "title": "Unrestricted SQL instance public access",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The SQL instance has an authorized network set to 0.0.0.0/0, allowing public access from any IP address."
    },
    {
      "check_id": "CKV_GCP_17",
      "title": "SQL instance not requiring SSL/TLS connections",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The SQL instance has require_ssl set to false, allowing unencrypted connections."
    },
    {
      "check_id": "CKV_GCP_82",
      "title": "SQL instance deletion protection disabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The SQL instance has deletion_protection set to false, making it possible to accidentally delete the instance."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Removed public access from authorized networks, enabled SSL/TLS requirement, and enabled deletion protection for the SQL instance."
}
